import base64,gzip,json,hashlib,os,subprocess,pathlib,datetime
p=pathlib.Path('/opt/dashboard/database/mysql')
p.mkdir(parents=True,exist_ok=True,mode=0o700)
os.chmod(p,0o700)
d=json.loads(gzip.decompress(base64.b64decode('')))
sql=d['sql'];m=d['manifest']
assert hashlib.sha256(sql.encode()).hexdigest()==m['sha256']
for name,text in [('001_schema.sql',sql),('manifest.json',json.dumps(m,ensure_ascii=False,indent=2))]:
 f=p/name
 if f.exists():
  assert f.read_text()==text,'Existing deployment file differs; stop for review'
 else:
  f.write_text(text);os.chmod(f,0o600)
def mysql(query):
 r=subprocess.run(['docker','exec','-i','pet-db','sh','-c','MYSQL_PWD="$MYSQL_ROOT_PASSWORD" exec mysql -uroot --default-character-set=utf8mb4 -NB'],input=query,text=True,capture_output=True)
 if r.returncode: raise RuntimeError(r.stderr)
 return r.stdout.strip()
assert not mysql("SELECT SCHEMA_NAME FROM information_schema.SCHEMATA WHERE SCHEMA_NAME='dashboard';"),'dashboard exists; stop to avoid overwriting'
print('Applying schema',m['sha256'],flush=True)
mysql(sql)
rows=mysql("SELECT TABLE_NAME,COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='dashboard' ORDER BY TABLE_NAME,ORDINAL_POSITION;")
actual={}
for row in rows.splitlines():
 t,c=row.split('\t');actual.setdefault(t,[]).append(c)
assert actual==m['table_columns'], 'Column mismatch'
fk=int(mysql("SELECT COUNT(*) FROM information_schema.REFERENTIAL_CONSTRAINTS WHERE CONSTRAINT_SCHEMA='dashboard';"))
ck=int(mysql("SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA='dashboard' AND CONSTRAINT_TYPE='CHECK';"))
assert fk==m['foreign_keys'],(fk,m['foreign_keys'])
assert ck==m['check_constraints'],(ck,m['check_constraints'])
result={'verified_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'mysql_version':mysql('SELECT VERSION();'),'database':'dashboard','table_count':len(actual),'column_count':sum(map(len,actual.values())),'foreign_keys':fk,'check_constraints':ck,'schema_sha256':m['sha256'],'existing_services_changed':False,'app_accounts_created':False}
(p/'verification.json').write_text(json.dumps(result,ensure_ascii=False,indent=2));os.chmod(p/'verification.json',0o600)
print(json.dumps(result,ensure_ascii=False,indent=2),flush=True)
